SELECT EXISTS (
  SELECT 1 FROM order_package_allocations WHERE order_id=#{orderId}
    AND carrier=#{carrier} AND tracking_number=#{trackingNumber}
)

SELECT COALESCE(SUM(l.quantity),0) FROM order_package_lines l
JOIN order_package_allocations p ON p.package_id=l.package_id
WHERE l.order_line_id=#{orderLineId} AND p.warehouse_id=#{warehouseId}
